#include <stdio.h>

/* 模拟 16 位变长操作码译码：每段 4 位，全 1 码点保留给下一级扩展 */
void decode(unsigned int ins) {
    unsigned int top4 = (ins >> 12) & 0xF;
    if (top4 != 0xF) {                                   /* 非全 1：三地址 */
        printf("译码：三地址指令，操作码=%X，三个地址码=%X %X %X\n",
               top4, (ins >> 8) & 0xF, (ins >> 4) & 0xF, ins & 0xF);
    } else {
        unsigned int top8 = (ins >> 8) & 0xFF;
        if (top8 != 0xFF) {                              /* 1111 非全 1：二地址 */
            printf("译码：二地址指令，操作码=%X，两个地址码=%X %X\n",
                   top8, (ins >> 4) & 0xF, ins & 0xF);
        } else {
            unsigned int top12 = (ins >> 4) & 0xFFF;
            if (top12 != 0xFFF) {                        /* 1111 1111 非全 1：一地址 */
                printf("译码：一地址指令，操作码=%X，地址码=%X\n", top12, ins & 0xF);
            } else {                                     /* 全 1：零地址 */
                printf("译码：零地址指令，操作码=%X\n", ins & 0xF);
            }
        }
    }
}

int main() {
    unsigned int samples[] = {0x1234, 0xF234, 0xFF34, 0xFFF1, 0xFFFF};
    int n = 5;
    for (int i = 0; i < n; i++) decode(samples[i]);
    return 0;
}
